-- Nội thất LOD 3 Tòa B và Tòa E (sinh bởi Models_3D/scripts/07_import_lod3_b_e.py, nạp sau 01-05)
-- Dữ liệu số hóa từ model 3D + danh bạ phòng công khai, chưa kiểm chứng thực địa (verified = false)
BEGIN;
DELETE FROM rooms WHERE building_id = (SELECT id FROM buildings WHERE building_code = 'B');
DELETE FROM floors WHERE building_id = (SELECT id FROM buildings WHERE building_code = 'B');
DELETE FROM rooms WHERE building_id = (SELECT id FROM buildings WHERE building_code = 'E');
DELETE FROM floors WHERE building_id = (SELECT id FROM buildings WHERE building_code = 'E');
COMMIT;
